"use client";

import { cn } from "@/lib/utils";

import { CrmDataTable } from "./crm-data-table";
import { CrmDataTablePagination } from "./crm-data-table-pagination";
import { CrmDataTableToolbar } from "./crm-data-table-toolbar";
import type { CrmCustomer } from "./types";
import { useCrmTable } from "./use-crm-table";

export type { CrmCustomer } from "./types";

export type CrmDataTableBlockProps = {
  data: CrmCustomer[];
  className?: string;
};

export function CrmDataTableBlock({ data, className }: CrmDataTableBlockProps) {
  "use no memo";

  const controller = useCrmTable(data);
  const teams = Array.from(new Set(data.map((customer) => customer.team))).sort();

  return (
    <div className={cn("bg-background flex h-full min-h-0 flex-col", className)}>
      <CrmDataTableToolbar
        table={controller.table}
        teams={teams}
        density={controller.density}
        onDensityChange={controller.setDensity}
        searchInput={controller.searchInput}
        onSearchChange={controller.setSearchInput}
        teamFilter={controller.teamFilter}
        onTeamFilterChange={controller.setTeamFilter}
        selectedCount={controller.selectedCount}
        onClearSelection={controller.clearSelection}
        hasFilters={controller.hasFilters}
        onClearFilters={controller.clearFilters}
      />
      <CrmDataTable table={controller.table} density={controller.density} />
      <CrmDataTablePagination table={controller.table} />
    </div>
  );
}

"use client";

import type { ColumnDef } from "@tanstack/react-table";
import { formatDistanceToNow } from "date-fns";
import {
  ArrowDown,
  ArrowUp,
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
  ChevronsUpDown,
  EyeOff,
  MoreHorizontal,
  Pin,
  PinOff,
  TrendingDown,
  TrendingUp,
  X,
} from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";

import type { CRM_FEATURES, CrmColumn, CrmCoreTable } from "./crm-data-table-features";
import { ColumnFilter, CRM_FILTER_VARIANTS } from "./crm-data-table-filter";
import {
  currencyFormatter,
  dateFormatter,
  dicebearAvatar,
  ONLINE_TONE,
} from "./crm-data-table-format";
import type { CrmCustomer } from "./types";

export const CRM_COLUMN_LABELS: Record<string, string> = {
  account: "Account",
  location: "Location",
  website: "Website",
  lead: "Lead",
  team: "Team",
  amount: "Amount",
  stock: "Stonk",
  startDate: "Start Date",
  communication: "Communication",
  onlinePresence: "Online Presence",
  founded: "Founded",
  founders: "Founders",
  employees: "Employees",
  email: "Email",
  lastInteraction: "Last Interaction",
  responseRate: "Response Rate",
};

export function createCrmColumns(): Array<ColumnDef<typeof CRM_FEATURES, CrmCustomer, unknown>> {
  return [
    {
      id: "expander",
      enableSorting: false,
      enableHiding: false,
      enableColumnFilter: false,
      header: () => null,
      cell: ({ row }) =>
        row.getCanExpand() ? (
          <button
            type="button"
            onClick={row.getToggleExpandedHandler()}
            aria-label={row.getIsExpanded() ? "Collapse row" : "Expand row"}
            aria-expanded={row.getIsExpanded()}
            className="text-muted-foreground hover:text-foreground flex h-full w-full items-center justify-center transition-colors"
          >
            <ChevronRight
              className={cn("size-4 transition-transform", row.getIsExpanded() && "rotate-90")}
            />
          </button>
        ) : null,
    },
    {
      id: "select",
      enableSorting: false,
      enableHiding: false,
      enableColumnFilter: false,
      header: ({ table }) => (
        <div className="flex h-full items-center justify-center">
          <Checkbox
            aria-label="Select all rows"
            checked={
              table.getIsAllRowsSelected()
                ? true
                : table.getIsSomeRowsSelected()
                  ? "indeterminate"
                  : false
            }
            onCheckedChange={(value) => table.toggleAllRowsSelected(value === true)}
          />
        </div>
      ),
      cell: ({ row }) => (
        <div className="flex h-full items-center justify-center">
          <Checkbox
            aria-label={`Select ${row.original.account}`}
            checked={row.getIsSelected()}
            onCheckedChange={(value) => row.toggleSelected(value === true)}
          />
        </div>
      ),
    },
    {
      id: "index",
      enableSorting: false,
      enableHiding: false,
      enablePinning: false,
      enableColumnFilter: false,
      header: () => <div className="flex h-full items-center justify-center font-medium">#</div>,
      cell: ({ row }) => (
        <div className="flex h-full items-center justify-center">
          <span className="text-muted-foreground font-mono text-xs tabular-nums">
            {row.index + 1}
          </span>
        </div>
      ),
    },
    {
      accessorKey: "account",
      filterFn: "includesString",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Account" />
      ),
      enableHiding: false,
      cell: ({ row }) => (
        <div className="flex items-center gap-2">
          {/* eslint-disable-next-line @next/next/no-img-element -- DiceBear SVG avatar */}
          <img
            src={dicebearAvatar(row.original.account)}
            alt=""
            width={24}
            height={24}
            loading="lazy"
            decoding="async"
            className="bg-muted size-6 shrink-0 rounded-md"
          />
          <span className="font-medium">{row.original.account}</span>
        </div>
      ),
    },
    {
      accessorKey: "location",
      filterFn: "arrHas",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Location" />
      ),
      cell: ({ row }) => <span className="text-muted-foreground">{row.original.location}</span>,
    },
    {
      accessorKey: "website",
      filterFn: "includesString",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Website" />
      ),
      cell: ({ row }) => (
        <a
          href={`https://${row.original.website}`}
          target="_blank"
          rel="noreferrer"
          className="text-primary hover:underline"
        >
          {row.original.website}
        </a>
      ),
    },
    {
      accessorKey: "lead",
      filterFn: "arrHas",
      header: ({ column, table }) => <CrmColumnHeader column={column} table={table} title="Lead" />,
      cell: ({ row }) => (
        <div className="flex items-center gap-2">
          {/* eslint-disable-next-line @next/next/no-img-element -- DiceBear SVG avatar */}
          <img
            src={dicebearAvatar(row.original.lead)}
            alt=""
            width={24}
            height={24}
            loading="lazy"
            decoding="async"
            className="bg-muted size-6 shrink-0 rounded-full"
          />
          <span>{row.original.lead}</span>
        </div>
      ),
    },
    {
      accessorKey: "team",
      filterFn: "arrHas",
      header: ({ column, table }) => <CrmColumnHeader column={column} table={table} title="Team" />,
      cell: ({ row }) => <span className="text-muted-foreground">{row.original.team}</span>,
    },
    {
      accessorKey: "amount",
      filterFn: "inNumberRange",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Amount" />
      ),
      cell: ({ row }) => (
        <span className="font-medium tabular-nums">
          {currencyFormatter.format(row.original.amount)}
        </span>
      ),
    },
    {
      id: "stock",
      accessorFn: (row) => row.stock.change,
      filterFn: "inNumberRange",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Stonk" />
      ),
      cell: ({ row }) => {
        const { change } = row.original.stock;
        const up = change >= 0;

        return (
          <span
            className={cn(
              "inline-flex items-center gap-0.5 text-xs font-medium tabular-nums",
              up ? "text-emerald-500" : "text-red-500",
            )}
          >
            {up ? <TrendingUp className="size-3.5" /> : <TrendingDown className="size-3.5" />}
            {up ? "+" : ""}
            {change.toFixed(2)}%
          </span>
        );
      },
    },
    {
      accessorKey: "startDate",
      filterFn: "inDateRange",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Start Date" />
      ),
      cell: ({ row }) => (
        <span className="text-muted-foreground">
          {dateFormatter.format(new Date(row.original.startDate))}
        </span>
      ),
    },
    {
      accessorKey: "communication",
      filterFn: "arrHas",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Communication" />
      ),
      cell: ({ row }) => <Badge variant="outline">{row.original.communication}</Badge>,
    },
    {
      accessorKey: "onlinePresence",
      filterFn: "arrHas",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Online Presence" />
      ),
      cell: ({ row }) => (
        <span className="text-muted-foreground inline-flex items-center gap-1.5">
          <span
            className={`size-1.5 rounded-full ${ONLINE_TONE[row.original.onlinePresence]}`}
            aria-hidden
          />
          {row.original.onlinePresence}
        </span>
      ),
    },
    {
      accessorKey: "founded",
      filterFn: "inNumberRange",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Founded" />
      ),
      cell: ({ row }) => <span className="tabular-nums">{row.original.founded}</span>,
    },
    {
      accessorKey: "founders",
      filterFn: "includesString",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Founders" />
      ),
      cell: ({ row }) => <span className="text-muted-foreground">{row.original.founders}</span>,
    },
    {
      accessorKey: "employees",
      filterFn: "inNumberRange",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Employees" />
      ),
      cell: ({ row }) => <span className="tabular-nums">{row.original.employees}</span>,
    },
    {
      accessorKey: "email",
      filterFn: "includesString",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Email" />
      ),
      cell: ({ row }) => (
        <a href={`mailto:${row.original.email}`} className="text-primary hover:underline">
          {row.original.email}
        </a>
      ),
    },
    {
      accessorKey: "lastInteraction",
      filterFn: "inDateRange",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Last Interaction" />
      ),
      cell: ({ row }) => (
        <span className="text-muted-foreground">
          {formatDistanceToNow(new Date(row.original.lastInteraction), { addSuffix: true })}
        </span>
      ),
    },
    {
      accessorKey: "responseRate",
      filterFn: "inNumberRange",
      header: ({ column, table }) => (
        <CrmColumnHeader column={column} table={table} title="Response Rate" />
      ),
      cell: ({ row }) => (
        <div className="flex items-center gap-2">
          <div className="bg-muted h-1.5 w-16 overflow-hidden rounded-full">
            <div
              className="bg-primary h-full rounded-full"
              style={{ width: `${row.original.responseRate}%` }}
            />
          </div>
          <span className="text-muted-foreground text-xs tabular-nums">
            {row.original.responseRate}%
          </span>
        </div>
      ),
    },
    {
      id: "actions",
      enableSorting: false,
      enableHiding: false,
      enablePinning: false,
      enableColumnFilter: false,
      header: () => <span className="sr-only">Actions</span>,
      cell: ({ row }) => {
        const pinned = row.getIsPinned();
        return (
          <div className="flex h-full items-center justify-center">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <button
                  type="button"
                  aria-label={`Actions for ${row.original.account}`}
                  className="text-muted-foreground hover:bg-muted hover:text-foreground flex size-7 items-center justify-center rounded-md transition-colors"
                >
                  <MoreHorizontal className="size-4" />
                </button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-40">
                <DropdownMenuItem onClick={() => row.pin(pinned === "top" ? false : "top")}>
                  {pinned === "top" ? <PinOff /> : <Pin />}
                  {pinned === "top" ? "Unpin row" : "Pin row to top"}
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        );
      },
    },
  ];
}

export function CrmColumnHeader({
  column,
  table,
  title,
}: {
  column: CrmColumn;
  table: CrmCoreTable;
  title: string;
}) {
  "use no memo";

  if (
    !column.getCanSort() &&
    !column.getCanHide() &&
    !column.getCanPin() &&
    !column.getCanFilter()
  ) {
    return <div className="flex h-full items-center px-2 font-medium">{title}</div>;
  }

  const sorted = column.getIsSorted();
  const pinned = column.getIsPinned();

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <button
          type="button"
          className="hover:bg-muted focus-visible:ring-ring/50 flex h-full w-full items-center justify-between gap-1 px-2 text-left font-medium outline-none focus-visible:ring-[3px] focus-visible:ring-inset"
        >
          <span className="flex min-w-0 items-center gap-1">
            {pinned && <Pin className="text-primary size-3 shrink-0" aria-hidden="true" />}
            <span className="truncate">{title}</span>
          </span>
          {sorted === "asc" ? (
            <ArrowUp className="size-3.5 shrink-0" />
          ) : sorted === "desc" ? (
            <ArrowDown className="size-3.5 shrink-0" />
          ) : (
            <ChevronsUpDown className="text-muted-foreground size-3.5 shrink-0" />
          )}
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="w-56">
        {column.getCanSort() && (
          <>
            <DropdownMenuItem onClick={() => column.toggleSorting(false)}>
              <ArrowUp />
              Ascending
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => column.toggleSorting(true)}>
              <ArrowDown />
              Descending
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => column.clearSorting()}>
              <X />
              No sorting
            </DropdownMenuItem>
            <DropdownMenuSeparator />
          </>
        )}
        {column.getCanFilter() && CRM_FILTER_VARIANTS[column.id] && (
          <>
            <DropdownMenuLabel>Filter</DropdownMenuLabel>
            <ColumnFilter column={column} variant={CRM_FILTER_VARIANTS[column.id]} />
            {column.getFilterValue() !== undefined && (
              <DropdownMenuItem onClick={() => column.setFilterValue(undefined)}>
                <X />
                Clear filter
              </DropdownMenuItem>
            )}
            <DropdownMenuSeparator />
          </>
        )}
        {column.getCanPin() && (
          <>
            <ColumnPinningItems column={column} />
            <DropdownMenuSeparator />
          </>
        )}
        {column.getCanHide() && (
          <>
            <DropdownMenuItem
              disabled={column.getIsFirstColumn()}
              onClick={() => moveColumn(table, column.id, "start")}
            >
              <ChevronsLeft />
              Move to left end
            </DropdownMenuItem>
            <DropdownMenuItem
              disabled={column.getIsFirstColumn()}
              onClick={() => moveColumn(table, column.id, "left")}
            >
              <ChevronLeft />
              Move left
            </DropdownMenuItem>
            <DropdownMenuItem
              disabled={column.getIsLastColumn()}
              onClick={() => moveColumn(table, column.id, "right")}
            >
              <ChevronRight />
              Move right
            </DropdownMenuItem>
            <DropdownMenuItem
              disabled={column.getIsLastColumn()}
              onClick={() => moveColumn(table, column.id, "end")}
            >
              <ChevronsRight />
              Move to right end
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={() => column.toggleVisibility(false)}>
              <EyeOff />
              Hide column
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function ColumnPinningItems({ column }: { column: CrmColumn }) {
  const pinned = column.getIsPinned();

  return (
    <>
      <DropdownMenuItem disabled={pinned === "start"} onClick={() => column.pin("start")}>
        <Pin />
        Pin to left
      </DropdownMenuItem>
      <DropdownMenuItem disabled={pinned === "end"} onClick={() => column.pin("end")}>
        <Pin />
        Pin to right
      </DropdownMenuItem>
      {pinned && (
        <DropdownMenuItem onClick={() => column.pin(false)}>
          <PinOff />
          Unpin
        </DropdownMenuItem>
      )}
    </>
  );
}

function moveColumn(
  table: CrmCoreTable,
  columnId: string,
  direction: "left" | "right" | "start" | "end",
) {
  const order = table.getAllLeafColumns().map((column) => column.id);
  const from = order.indexOf(columnId);
  if (from === -1) return;

  const to =
    direction === "left"
      ? from - 1
      : direction === "right"
        ? from + 1
        : direction === "start"
          ? 0
          : order.length - 1;

  if (to < 0 || to >= order.length || to === from) return;

  const next = [...order];
  next.splice(from, 1);
  next.splice(to, 0, columnId);
  table.setColumnOrder(next);
}

"use client";

import type { KeyboardEvent } from "react";

import { DropdownMenuCheckboxItem } from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";

import type { CrmColumn } from "./crm-data-table-features";

export type CrmFilterVariant = "text" | "select" | "number" | "date";

export const CRM_FILTER_VARIANTS: Record<string, CrmFilterVariant> = {
  account: "text",
  location: "select",
  website: "text",
  lead: "select",
  team: "select",
  amount: "number",
  stock: "number",
  startDate: "date",
  communication: "select",
  onlinePresence: "select",
  founded: "number",
  founders: "text",
  employees: "number",
  email: "text",
  lastInteraction: "date",
  responseRate: "number",
};

const stopMenuKeyboard = (event: KeyboardEvent) => event.stopPropagation();

export function ColumnFilter({
  column,
  variant,
}: {
  column: CrmColumn;
  variant: CrmFilterVariant;
}) {
  switch (variant) {
    case "text":
      return <TextFilter column={column} />;
    case "select":
      return <SelectFilter column={column} />;
    case "number":
      return <NumberRangeFilter column={column} />;
    case "date":
      return <DateRangeFilter column={column} />;
  }
}

function TextFilter({ column }: { column: CrmColumn }) {
  const value = (column.getFilterValue() as string | undefined) ?? "";

  return (
    <div className="p-1">
      <Input
        value={value}
        placeholder="Contains..."
        className="h-7 text-xs"
        onKeyDown={stopMenuKeyboard}
        onChange={(event) => column.setFilterValue(event.target.value || undefined)}
      />
    </div>
  );
}

function SelectFilter({ column }: { column: CrmColumn }) {
  const selected = (column.getFilterValue() as string[] | undefined) ?? [];
  const values = Array.from(column.getFacetedUniqueValues().entries()).sort((a, b) =>
    String(a[0]).localeCompare(String(b[0])),
  );

  if (values.length === 0) {
    return <p className="text-muted-foreground px-2 py-1.5 text-xs">No values</p>;
  }

  return (
    <div className="max-h-56 overflow-y-auto">
      {values.map(([value, count]) => {
        const label = String(value);

        return (
          <DropdownMenuCheckboxItem
            key={label}
            checked={selected.includes(label)}
            onSelect={(event) => event.preventDefault()}
            onCheckedChange={(checked) => {
              const next = checked
                ? [...selected, label]
                : selected.filter((item) => item !== label);
              column.setFilterValue(next.length > 0 ? next : undefined);
            }}
          >
            <span className="flex-1 truncate">{label}</span>
            <span className="text-muted-foreground tabular-nums">{count}</span>
          </DropdownMenuCheckboxItem>
        );
      })}
    </div>
  );
}

function NumberRangeFilter({ column }: { column: CrmColumn }) {
  const [min, max] = (column.getFilterValue() as [number?, number?] | undefined) ?? [];

  const update = (nextMin: number | undefined, nextMax: number | undefined) => {
    const empty = nextMin === undefined && nextMax === undefined;
    column.setFilterValue(empty ? undefined : [nextMin, nextMax]);
  };

  return (
    <div className="flex items-center gap-1.5 p-1">
      <Input
        type="number"
        value={min ?? ""}
        placeholder="Min"
        className="h-7 text-xs"
        onKeyDown={stopMenuKeyboard}
        onChange={(event) =>
          update(event.target.value === "" ? undefined : Number(event.target.value), max)
        }
      />
      <span className="text-muted-foreground text-xs">to</span>
      <Input
        type="number"
        value={max ?? ""}
        placeholder="Max"
        className="h-7 text-xs"
        onKeyDown={stopMenuKeyboard}
        onChange={(event) =>
          update(min, event.target.value === "" ? undefined : Number(event.target.value))
        }
      />
    </div>
  );
}

function DateRangeFilter({ column }: { column: CrmColumn }) {
  const [from, to] = (column.getFilterValue() as [string?, string?] | undefined) ?? [];

  const update = (nextFrom: string | undefined, nextTo: string | undefined) => {
    const empty = nextFrom === undefined && nextTo === undefined;
    column.setFilterValue(empty ? undefined : [nextFrom, nextTo]);
  };

  return (
    <div className="flex flex-col gap-1.5 p-1">
      <Input
        type="date"
        value={from ?? ""}
        className="h-7 text-xs"
        onKeyDown={stopMenuKeyboard}
        onChange={(event) => update(event.target.value || undefined, to)}
      />
      <Input
        type="date"
        value={to ?? ""}
        className="h-7 text-xs"
        onKeyDown={stopMenuKeyboard}
        onChange={(event) => update(from, event.target.value || undefined)}
      />
    </div>
  );
}

import type { CrmOnlinePresence } from "./types";

export const currencyFormatter = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
});

export const dateFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
});

export const ONLINE_TONE: Record<CrmOnlinePresence, string> = {
  Active: "bg-emerald-500",
  Idle: "bg-amber-500",
  Offline: "bg-muted-foreground",
};

export function dicebearAvatar(seed: string, size = 24): string {
  return `https://api.dicebear.com/10.x/blobs/svg?seed=${encodeURIComponent(seed)}&size=${size}`;
}

"use client";

import { ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

import type { CrmTable } from "./crm-data-table-features";

const PAGE_SIZE_OPTIONS = [10, 20, 50] as const;

export function CrmDataTablePagination({ table }: { table: CrmTable }) {
  "use no memo";

  const { pageIndex, pageSize } = table.state.pagination;
  const rowCount = table.getRowCount();
  const canPrevious = table.getCanPreviousPage();
  const canNext = table.getCanNextPage();
  const firstRow = rowCount === 0 ? 0 : pageIndex * pageSize + 1;
  const lastRow = Math.min(rowCount, (pageIndex + 1) * pageSize);

  return (
    <div className="flex h-10 shrink-0 items-center justify-between gap-2 px-3 text-xs">
